function dspError(code, detail, statusCode) {
    return {
        statusCode: statusCode || 401,
        headers: { 'Content-Type': 'application/json' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}

// prep: the counterparty is the presentation's audience: its base URL as this
// connector calls it (msg.payload.providerBaseUrl from the consumer flow, or
// msg.payload.counterparty), falling back to DSP_PEER_ENDPOINT. The
// counterparty accepts its own base URL in DSP_IAM_AUDIENCE. A fresh nonce per
// presentation (the counterparty refuses a nonce it has seen), and a
// correlation id for the iam.issue event.
function reject(code, detail, statusCode) {
    Object.assign(msg, dspError(code, detail, statusCode));
    msg.iamIssueRejected = true;
    return [null, msg];
}

const reqHeaders = (msg.req && msg.req.headers) || {};
msg._iamCorrelationId = reqHeaders['x-correlation-id'] || crypto.randomUUID();
if (msg.res && typeof msg.res.set === 'function') msg.res.set('X-Correlation-Id', msg._iamCorrelationId);

const p = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const audience = String(p.counterparty || p.providerBaseUrl || env.get('DSP_PEER_ENDPOINT') || '').replace(/\/+$/, '');
if (!audience) return reject('config_missing', 'no counterparty (msg.payload.providerBaseUrl, msg.payload.counterparty or DSP_PEER_ENDPOINT)', 500);
const nonce = (msg.payload && msg.payload.nonce) || crypto.randomUUID();
msg._iamIssue = { audience: audience, nonce: nonce };
return [msg, null];

// The connector's participant credential from its W-Stack tenant's storage:
// POST /v1/tenants/{tenant}/storage/{region}/{country}/{account}/credentials
// with a DCQL query for an SD-JWT VC of the participant credential type
// (DSP_PARTICIPANT_VCT). Region, country and account are where the tenant's
// retrieval service filed it when the connector accepted the offer.
function dspError(code, detail, statusCode) {
    return {
        statusCode: statusCode || 401,
        headers: { 'Content-Type': 'application/json' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}
function reject(code, detail, statusCode) {
    Object.assign(msg, dspError(code, detail, statusCode));
    msg.iamIssueRejected = true;
    return [null, msg];
}

const base = (env.get('OCM_STORAGE_URL') || '').replace(/\/+$/, '');
const tenant = env.get('OCM_TENANT') || '';
const region = env.get('OCM_REGION') || '';
const country = env.get('OCM_COUNTRY') || '';
const account = env.get('OCM_ACCOUNT') || '';
const vct = env.get('DSP_PARTICIPANT_VCT') || '';
if (!base || !tenant || !region || !country || !account || !vct) {
    return reject('config_missing', 'OCM_STORAGE_URL, OCM_TENANT, OCM_REGION, OCM_COUNTRY, OCM_ACCOUNT and DSP_PARTICIPANT_VCT are required — fail closed', 500);
}
msg._iamOrigPayload = msg.payload;
msg.url = base + '/v1/tenants/' + [tenant, 'storage', region, country, account].map(encodeURIComponent).join('/') + '/credentials';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { credentials: [{ id: 'participant', format: 'dc+sd-jwt', meta: { vct_values: [vct] } }] };
return [msg, null];

// The storage answer: {groups: [{credentials: {<id>: {data}}}]} for the DCQL
// query, {} when nothing matches. Takes the participant credential that
// expires last among the valid ones; none -> abort (never present nothing).
function dspError(code, detail, statusCode) {
    return {
        statusCode: statusCode || 401,
        headers: { 'Content-Type': 'application/json' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}
function reject(code, detail, statusCode) {
    if ('_iamOrigPayload' in msg) { msg.payload = msg._iamOrigPayload; delete msg._iamOrigPayload; }
    Object.assign(msg, dspError(code, detail, statusCode));
    msg.iamIssueRejected = true;
    return [null, msg];
}

const resp = msg.payload;
const code = msg.statusCode;
if ('_iamOrigPayload' in msg) { msg.payload = msg._iamOrigPayload; delete msg._iamOrigPayload; }
delete msg.statusCode;
if (code !== 200 || !resp || typeof resp !== 'object') return reject('storage_unavailable', 'tenant storage did not answer the query', 502);
const nowS = Math.floor(Date.now() / 1000);
const payloadOf = (sdjwt) => {
    try { return JSON.parse(Buffer.from(sdjwt.split('~')[0].split('.')[1], 'base64url').toString('utf8')); } catch (e) { return null; }
};
let best = null;
for (const g of Array.isArray(resp.groups) ? resp.groups : []) {
    for (const c of Object.values((g && g.credentials) || {})) {
        const sdjwt = c && typeof c.data === 'string' ? c.data : null;
        const p = sdjwt && sdjwt.includes('~') ? payloadOf(sdjwt) : null;
        if (!p || (typeof p.exp === 'number' && p.exp <= nowS)) continue;
        if (!best || (p.exp || Infinity) > (best.p.exp || Infinity)) best = { sdjwt, p };
    }
}
if (!best) return reject('no_credential', 'no valid participant credential in the tenant storage — abort', 500);
msg._iamIssue.vcToken = best.sdjwt;
return [msg, null];

// Ask the tenant's crypto provider for the presentation: it adds the
// key-binding JWT (audience = the counterparty, the nonce, sd_hash), signed
// with the tenant's key, the one the credential binds. Of the claims listed in
// DSP_IAM_DISCLOSE, those the credential holds as disclosures are presented
// (claims the issuer did not make selectively disclosable are always there).
// This flow never signs anything itself.
function dspError(code, detail, statusCode) {
    return {
        statusCode: statusCode || 401,
        headers: { 'Content-Type': 'application/json' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}
function reject(code, detail, statusCode) {
    Object.assign(msg, dspError(code, detail, statusCode));
    msg.iamIssueRejected = true;
    return [null, msg];
}

const base = (env.get('OCM_CRYPTO_URL') || '').replace(/\/+$/, '');
const ns = env.get('OCM_KEY_NAMESPACE') || '';
const group = env.get('OCM_KEY_GROUP') || '';
const key = env.get('OCM_KEY') || '';
if (!base || !ns || !key) return reject('config_missing', 'OCM_CRYPTO_URL, OCM_KEY_NAMESPACE and OCM_KEY are required — fail closed', 500);
const wanted = (env.get('DSP_IAM_DISCLOSE') || 'legalName,participantRoles').split(',').map((s) => s.trim()).filter(Boolean);
const held = msg._iamIssue.vcToken.split('~').slice(1).filter(Boolean).map((d) => {
    try { const a = JSON.parse(Buffer.from(d, 'base64url').toString('utf8')); return Array.isArray(a) && a.length === 3 ? a[1] : null; } catch (e) { return null; }
});
const frame = wanted.filter((n) => held.includes(n));
msg._iamOrigPayload = msg.payload;
msg.url = base + '/v1/presentation/proof';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    namespace: ns,
    group: group,
    key: key,
    format: 'dc+sd-jwt',
    presentation: msg._iamIssue.vcToken,
    aud: msg._iamIssue.audience,
    nonce: msg._iamIssue.nonce,
    disclosureFrame: frame
};
return [msg, null];

// The crypto provider's answer is the presentation itself: the SD-JWT VC, its
// presented disclosures and the key-binding JWT. Anything else -> abort. On
// success only msg.vpToken carries it: facis-dsp-consumer.json puts it in
// Authorization: Bearer; the payload stays the caller's (never leak the
// credential into downstream logs or evidence).
function dspError(code, detail, statusCode) {
    return {
        statusCode: statusCode || 401,
        headers: { 'Content-Type': 'application/json' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}
function reject(code, detail, statusCode) {
    if ('_iamOrigPayload' in msg) { msg.payload = msg._iamOrigPayload; delete msg._iamOrigPayload; }
    Object.assign(msg, dspError(code, detail, statusCode));
    msg.iamIssueRejected = true;
    return msg;
}

const resp = msg.payload;
const code = msg.statusCode;
if ('_iamOrigPayload' in msg) { msg.payload = msg._iamOrigPayload; delete msg._iamOrigPayload; }
delete msg.statusCode;
const token = typeof resp === 'string' ? resp.trim() : null;
const parts = token ? token.split('~') : [];
const kb = parts.length >= 2 ? parts[parts.length - 1] : '';
if (code !== 200 || !token || kb.split('.').length !== 3 || !token.startsWith(msg._iamIssue.vcToken.split('~')[0] + '~')) {
    return reject('proof_failed', 'crypto provider returned no presentation — abort', 502);
}
msg._iamIssue.vpJwt = token;
msg.vpToken = token;
return msg;

// Symmetric with iam.verify: the issuance result is logged as a structured event with
// the correlation id.
const event = {
    event: 'iam.issue',
    correlationId: msg._iamCorrelationId || null,
    at: new Date().toISOString(),
    result: (msg._iamIssue && msg._iamIssue.vpJwt) ? 'issued' : 'aborted',
    aud: (msg._iamIssue && msg._iamIssue.audience) || null,
    code: (msg.iamIssueRejected && msg.payload && msg.payload['dspace:code']) || null
};
node.warn(JSON.stringify(event));
const log = global.get('iamIssueEvents') || [];
log.push(event);
global.set('iamIssueEvents', log);
return msg;
